behaviors.source:
on tick
  let bow = water_height(22.0 - 12, 40.0 - 4)
  let stern = water_height(22.0 + 12, 40.0 + 4)
  let port = water_height(22.0 - 1.5, 40.0 + 4)
  let starboard = water_height(22.0 + 1.5, 40.0 - 4)
  let mid = (bow + stern + port + starboard) / 4
  self.position = (22.0, mid * 0.8 - 0.1, 40.0)
  self.rotation = ((port - starboard) * 4, 200 + sin(time * 0.11) * 1.5, (bow - stern) * 2.2)
end
